INSERT INTO projects (id, title, category, year, tags, cover, description, detail, gallery) VALUES ('tasky', 'Tasky', 'uiux', 2025, ARRAY['Mobile App', 'Task Management', 'UI Design'], '/images/projects/uiux/tasky-cover.png', 'Desain aplikasi mobile manajemen tugas dengan antarmuka yang bersih, intuitif, dan fokus pada produktivitas pengguna.', 'Tasky merupakan proyek desain aplikasi mobile manajemen tugas yang berfokus pada efisiensi dan kenyamanan produktivitas pengguna harian. Proses perancangan dimulai dari riset mendalam terhadap kebiasaan pengguna, penyusunan user flow yang intuitif, hingga perancangan komponen UI yang responsif.

Dalam pengerjaannya, setiap layar dirancang secara cermat agar informasi tugas dapat dipindai dengan cepat. Sistem desain yang konsisten memastikan interaksi terasa alami sehingga pengguna dapat mengelola pekerjaan mereka tanpa kendala visual maupun teknis.', ARRAY['/images/projects/uiux/ui/tasky-m-1.png', '/images/projects/uiux/ui/tasky-m-2.png', '/images/projects/uiux/ui/tasky-m-3.png', '/images/projects/uiux/ui/tasky-m-4.png', '/images/projects/uiux/ui/tasky-m-5.png', '/images/projects/uiux/ui/tasky-m-6.png']) ON CONFLICT (id) DO NOTHING;
INSERT INTO projects (id, title, category, year, tags, cover, description, detail, gallery) VALUES ('ssh', 'SSH', 'uiux', 2025, ARRAY['Mobile App', 'UI Design'], '/images/projects/uiux/ssh-cover.png', 'Perancangan antarmuka aplikasi mobile modern yang mengutamakan kenyamanan dan kejelasan informasi bagi pengguna.', 'SSH adalah perancangan antarmuka aplikasi mobile modern yang mengutamakan kenyamanan dan kejelasan informasi. Fokus utama proyek ini adalah membangun hierarki visual yang jelas, navigasi yang intuitif, serta konsistensi komponen sehingga pengguna merasa mudah saat menjelajahi fitur-fitur aplikasi.', ARRAY['/images/projects/uiux/ui/ssh-m-1.png', '/images/projects/uiux/ui/ssh-m-2.png', '/images/projects/uiux/ui/ssh-m-3.png', '/images/projects/uiux/ui/ssh-m-4.png']) ON CONFLICT (id) DO NOTHING;
INSERT INTO projects (id, title, category, year, tags, cover, description, detail, gallery) VALUES ('samling', 'Samling', 'uiux', 2025, ARRAY['IoT', 'UX Design', 'Design System'], '/images/projects/uiux/ui/samling-m-1.png', 'Platform integrasi IoT dan web untuk memantau kapasitas tempat sampah — Juara 1 AREK_AI FESTIKA Jatim 2025.', '### Samling — Smart Waste Management Platform

Samling adalah sistem berbasis data yang mengintegrasikan IoT dan web untuk mendukung digitalisasi pengelolaan sampah. Platform ini memantau kapasitas tempat sampah secara *real-time*, mengoptimalkan rute pengangkutan, serta menghubungkan Tempat Penampungan Sementara (TPS) dengan mitra industri daur ulang.

**Integrasi Pengguna:**
• Warga: Melaporkan kapasitas dan timbulan sampah lingkungan secara mandiri.
• Petugas: Mengakses rute logistik pengangkutan dan panduan pemilahan yang efisien.
• Administrator: Memantau analitik data limbah regional dan mengelola permintaan daur ulang.

**Metodologi:**
• Problem-Driven Design: Memastikan solusi berakar pada masalah nyata di lapangan.
• Riset Campuran: Analisis data rujukan nasional serta riset empathize terhadap 70+ responden.

**Peran Tim:**
• Aditya Pratama Putra: Researcher & UX Designer
• Agung Dwi Saputra: AI Prompter & UI Engineer', ARRAY['/images/projects/uiux/ui/samling-m-1.png', '/images/projects/uiux/ui/samling-m-2.png', '/images/projects/uiux/ui/samling-m-3.png', '/images/projects/uiux/ui/samling-m-4.png', '/images/projects/uiux/ui/samling-m-5.png']) ON CONFLICT (id) DO NOTHING;
INSERT INTO projects (id, title, category, year, tags, cover, description, detail, gallery) VALUES ('rc-brand', 'Brand Identity RC', 'brand', 2025, ARRAY['Brand Identity', 'Logo'], '/images/projects/brand design/rc-cover.png', 'Identitas visual brand yang modern dan mudah diingat, dari logo hingga penerapannya pada berbagai media.', 'Brand Identity RC adalah perancangan identitas visual yang modern dan mudah diingat. Pengerjaan dimulai dari riset brand, eksplorasi konsep logo, hingga penyusunan panduan penerapan logo pada berbagai media agar tetap konsisten di setiap titik sentuh dengan audiens.', ARRAY['/images/projects/brand design/rc-cover.png']) ON CONFLICT (id) DO NOTHING;
